import React, { useState } from 'react';
import axios from 'axios';
import './App.css';
import VehicleForm from './VehicleForm';
import StationForm from './StationForm';
import StepForm from './StepForm';
import SimulationComponent from './SimulationComponent';
import MapComponent from './MapComponent';
import 'leaflet/dist/leaflet.css';

function App() {
  const [showVehicleForm, setShowVehicleForm] = useState(false);
  const [showStationForm, setShowStationForm] = useState(false);
  const [showStepForm, setShowStepForm] = useState(false);
  const [vehicles, setVehicles] = useState([]);
  const [stations, setStations] = useState([]);
  const [steps, setSteps] = useState([]);
  const [newLocation, setNewLocation] = useState(null);
  const [selectingLocation, setSelectingLocation] = useState(false);

  const toggleVehicleForm = () => {
    setShowVehicleForm(!showVehicleForm);
  };

  const addVehicle = (vehicleData) => {
    if (!vehicleData.name || !vehicleData.battery_capacity || !vehicleData.consumption || !vehicleData.init_battery || !vehicleData.location || !vehicleData.start_time) {
      alert('Every field is required');
      return;
    }
    const newVehicle = {
      ...vehicleData,
      steps: []
    };

    axios.post('http://127.0.0.1:5000/add_vehicle', newVehicle)
      .then(response => {
        setVehicles([...vehicles, newVehicle]);
        console.log(response.data.message);
        setShowVehicleForm(false);
      })
      .catch(error => {
        console.error('Error adding vehicle:', error);
        alert('Error adding vehicle: ' + error.message);
      });
  };

  const toggleStationForm = () => {
    setShowStationForm(!showStationForm);
  };

  const addStation = (stationData) => {
    if (!stationData.name || !stationData.charging_speed || !stationData.price_per_kwh || !stationData.buy_price_per_kwh || !stationData.location || !stationData.discharging_speed) {
      alert('Every field is required');
      return;
    }

    axios.post('http://127.0.0.1:5000/add_station', stationData)
      .then(response => {
        setStations([...stations, stationData]);
        console.log(response.data.message);
        setShowStationForm(false);
      })
      .catch(error => {
        console.error('Error adding station:', error);
        alert('Error adding station: ' + error.message);
      });
  };

  const toggleStepForm = () => {
    setShowStepForm(!showStepForm);
  };

  const addStep = (stepData) => {
    const updatedVehicles = [...vehicles];
    const vehicleIndex = stepData.vehicleIndex;
      // Vérifiez si vehicleIndex est valide
    if (vehicleIndex >= 0 && vehicleIndex < updatedVehicles.length) {
      updatedVehicles[vehicleIndex].steps.push(stepData);
      setVehicles(updatedVehicles);
    } else {
      console.error('Invalid vehicleIndex:', vehicleIndex);
      // Gérer l'erreur ou informer l'utilisateur de l'indice de véhicule incorrect
      return;
    }

    updatedVehicles[vehicleIndex].steps.push(stepData);
    setVehicles(updatedVehicles);

    if (!stepData.stepType){
      alert('choose a type');
      return
    }


    axios.post('http://127.0.0.1:5000/add_step', stepData)
      .then(response => {
        setSteps([...steps, stepData]);
        console.log(response.data.message);
        setShowStepForm(false);
      })
      .catch(error => {
        console.error('Error adding step:', error);
        alert('Error adding step: ' + error.message);
      });
  };

  const runSimulation = () => {
    axios.post('http://127.0.0.1:5000/run_simulation')
      .then(response => {
        console.log(response.data.message);
      })
      .catch(error => {
        console.error('Error running simulation:', error);
        alert('Error running simulation: ' + error.message);
      });
  };

  const handleMapClick = (latlng) => {
    if (selectingLocation) {
      setNewLocation(latlng);
      setSelectingLocation(false);
    }
  };

  return (
    <div className="App">
      <div className="sidebar">
        <div className="controls-section">
          <button className="add-button" onClick={toggleVehicleForm}>Add vehicle</button>
          {showVehicleForm && (
            <VehicleForm onAddVehicle={addVehicle} onCancel={() => setShowVehicleForm(false)} initialLocation={newLocation} onSelectLocation={() => setSelectingLocation(true)} />
          )}
        </div>

        <div className="controls-section">
          <button className="add-button" onClick={toggleStationForm}>Add station</button>
          {showStationForm && (
            <StationForm onAddStation={addStation} onCancel={() => setShowStationForm(false)} initialLocation={newLocation} onSelectLocation={() => setSelectingLocation(true)} />
          )}
        </div>

        <div className="controls-section">
        <button className="add-button" onClick={toggleStepForm}>Add step</button>
        {showStepForm && (
          <StepForm
            onAddStep={addStep}
            onCancel={() => setShowStepForm(false)}
            vehicles={vehicles}
            stations={stations}
          />
        )}
      </div>

        <div className="simulation-controls">
          <button className="action-button" onClick={() => runSimulation()}>Run Simulation</button>
        </div>
      </div>

      <div className="map-container">
        <div className="map-frame">
          <MapComponent vehicles={vehicles} stations={stations} onMapClick={handleMapClick} />
        </div>
      </div>

      <div className="events-container">
        <SimulationComponent />
      </div>
    </div>
  );
}

export default App;
